// Formatar log de auditoria para conformidade LGPD
const input = $input.first().json;

// Campos obrigatórios
const camposObrigatorios = ['acao', 'usuario_id', 'usuario_email'];
const camposFaltando = camposObrigatorios.filter(campo => !input[campo]);

if (camposFaltando.length > 0) {
  throw new Error(`Campos obrigatórios faltando: ${camposFaltando.join(', ')}`);
}

// Lista de ações sensíveis que requerem auditoria
const acoesSensiveis = [
  'ALTERAR_ESCOPO',
  'ALTERAR_VALOR',
  'DELETAR_PROGRAMACAO',
  'AJUSTAR_MEDICAO',
  'ALTERAR_CONTRATO',
  'EXCLUIR_REGISTRO',
  'ALTERAR_PERMISSAO',
  'ACESSAR_DADOS_SENSIVEIS',
  'EXPORTAR_DADOS',
  'ALTERAR_USUARIO'
];

// Classificar nível de sensibilidade
let nivelSensibilidade = 'baixo';
if (acoesSensiveis.includes(input.acao)) {
  nivelSensibilidade = 'alto';
} else if (input.acao.startsWith('VISUALIZAR_')) {
  nivelSensibilidade = 'medio';
}

// Anonimizar dados pessoais sensíveis no registro
const dadosAntes = input.dados_antes || null;
const dadosDepois = input.dados_depois || null;

// Função para mascarar dados sensíveis
const mascarar = (texto) => {
  if (!texto) return texto;
  if (typeof texto !== 'string') return texto;

  // Mascarar CPF
  texto = texto.replace(/(\d{3})\.?(\d{3})\.?(\d{3})\-?(\d{2})/g, '$1.***.***-$4');
  // Mascarar telefone
  texto = texto.replace(/(\d{2})\s?(\d{4,5})\-?(\d{4})/g, '($1) ****-$3');

  return texto;
};

const auditLog = {
  // Identificação
  id: `AUD-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,

  // Ação realizada
  acao: input.acao,
  descricao: input.descricao || `Ação: ${input.acao}`,
  nivel_sensibilidade: nivelSensibilidade,

  // Quem realizou
  usuario_id: input.usuario_id,
  usuario_email: input.usuario_email,
  usuario_nome: input.usuario_nome || null,
  usuario_tipo: input.usuario_tipo || 'interno',

  // Contexto técnico
  ip_address: input.ip_address || 'não capturado',
  user_agent: input.user_agent || null,
  sessao_id: input.sessao_id || null,

  // Entidade afetada
  entidade: input.entidade || null,
  entidade_id: input.entidade_id || null,

  // Dados (para rastreabilidade)
  dados_antes: dadosAntes ? JSON.stringify(dadosAntes) : null,
  dados_depois: dadosDepois ? JSON.stringify(dadosDepois) : null,

  // Metadados
  origem: input.origem || 'sistema',
  modulo: input.modulo || null,

  // Timestamps
  timestamp: new Date().toISOString(),
  timestamp_unix: Date.now(),

  // Retenção (LGPD - configurável)
  data_expiracao: new Date(Date.now() + (5 * 365 * 24 * 60 * 60 * 1000)).toISOString() // 5 anos
};

// Determinar se precisa notificar admin
const notificarAdmin = nivelSensibilidade === 'alto' || 
                       input.acao.includes('DELETAR') || 
                       input.acao.includes('EXCLUIR');

return {
  json: {
    log: auditLog,
    notificar_admin: notificarAdmin
  }
};

